WITH flattened AS (SELECT id, service, log_ts, status_code, attr_key, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS attr_key, v) SELECT attr_key, service, COUNT(*) FILTER (WHERE attr_key = 'trace') AS trace_rows, SUM(CASE WHEN attr_key = 'version' THEN status_code ELSE 0 END) AS version_status_code, COUNT(*) FILTER (WHERE attr_key = 'trace') AS trace_rows_2, ROUND(AVG(status_code), 2) AS avg_status_code, ROUND(SUM(status_code) / NULLIF(COUNT(CASE WHEN service = 'auth' THEN 1 END), 0), 2) AS status_code_per_auth FROM flattened GROUP BY attr_key, service ORDER BY status_code_per_auth NULLS FIRST
